package org.apache.commons.math3.genetics;

import org.apache.commons.lang3.builder.EqualsBuilder;
import org.junit.*;
import static org.junit.Assert.*;

public class ElitisticListPopulationSymflowerTest {
	@Test
	public void getElitismRate1() {
		ElitisticListPopulation e = new ElitisticListPopulation(0, 0.);
		double expected = 0.;
		double actual = e.getElitismRate();

		assertEquals(expected, actual, 0.0000001D);
	}

	@Test
	public void setElitismRate2() {
		ElitisticListPopulation e = new ElitisticListPopulation(0, 0.);
		double elitismRate = 0.;
		e.setElitismRate(elitismRate);

		ElitisticListPopulation eExpected = new ElitisticListPopulation(0, 0.);

		assertTrue(EqualsBuilder.reflectionEquals(eExpected, e, false, null, true));
	}
}
